/* ---------------- German. One language is one file like this; src/lang.js explains how it is used. ----------------
   words: a whole English line, or one part of a line between " · ", with its German.
   rules: the same for lines with a number or a name in them. The first rule that fits wins; a rule that answers null is passed over.
   help:  the Help page's answers, by topic id (src/helpdata.js has the English). A button named in **bold** keeps its English name
          when its screen is still in English, so it can be found.
   Covered so far: the sidebar, Today, the welcome, Find anything, Help, and the feedback page in a returned paper. */
const DE_NUM = { no: 0, one: 1, two: 2, three: 3, four: 4, five: 5, six: 6, seven: 7, eight: 8, nine: 9, ten: 10, eleven: 11, twelve: 12 };
const deN = w => { const k = String(w).toLowerCase(); return k in DE_NUM ? DE_NUM[k] : +w; };
const deP = (n, one, many) => n + ' ' + (n === 1 ? one : many);
const deLast = s => s === 'the last set of papers' ? 'beim letzten Stapel Arbeiten' : 'bei ' + s;
// The line under Today's date: what she teaches, then what is waiting.
function deHomeSay(k) {
  const m = /^(?:(No classes today\.|(\w+) class(?:es)? today\.) ?)?(.*)$/.exec(k); if (!m) return null;
  let teach = '', work = '';
  if (m[1]) teach = m[2] ? 'Heute ' + deP(deN(m[2]), 'Klasse', 'Klassen') + '.' : 'Heute kein Unterricht.';
  const w = m[3];
  let x;
  if (!w) work = '';
  else if ((x = /^(\w+) sets? of papers to mark, (\w+) ready to hand back\.$/i.exec(w))) work = deP(deN(x[1]), 'Stapel', 'Stapel') + ' zu korrigieren, ' + deN(x[2]) + ' zur Rückgabe bereit.';
  else if ((x = /^(\w+) sets? of papers to mark\.$/i.exec(w))) work = deP(deN(x[1]), 'Stapel', 'Stapel') + ' zu korrigieren.';
  else if ((x = /^(\w+) sets? of papers ready to hand back\.$/i.exec(w))) work = deP(deN(x[1]), 'Stapel', 'Stapel') + ' zur Rückgabe bereit.';
  else if (/^nothing waiting to be marked\.$/i.test(w)) work = 'Nichts zu korrigieren.';
  else return null;
  if (!teach && !work) return null;
  return (teach + (work ? ' ' + work : '')).trim();
}
